package cn.iocoder.yudao.module.childhealth.controller.admin.device;
import cn.iocoder.yudao.framework.common.pojo.CommonResult; import cn.iocoder.yudao.module.childhealth.api.device.dto.DeviceCollectRequest; import cn.iocoder.yudao.module.childhealth.service.device.DeviceIntegrationService; import jakarta.annotation.Resource; import jakarta.validation.Valid; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.util.List; import static cn.iocoder.yudao.framework.common.pojo.CommonResult.success;
@RestController @RequestMapping("/childhealth/device") public class DeviceIntegrationController { @Resource private DeviceIntegrationService service; @PostMapping("/collect") @PreAuthorize("@ss.hasPermission('childhealth:device:collect')") public CommonResult<List<Long>> collect(@Valid @RequestBody DeviceCollectRequest request){return success(service.collect(request));} }
